int /* <=== gp_monitor_leave */ 
gp_monitor_leave(gp_monitor * mona)
{
    pthread_mutex_t * const mon = (pthread_mutex_t *)mona;
    int scode = 0;

#ifdef GS_RECURSIVE_MUTEXATTR
    scode = pthread_mutex_unlock(mon);
#else
    assert(((gp_pthread_recursive_t *)mona)->lcount > 0 && ((gp_pthread_recursive_t *)mona)->self_id != 0);

    if (pthread_equal(pthread_self(),((gp_pthread_recursive_t *)mona)->self_id)) {
      if ((--((gp_pthread_recursive_t *)mona)->lcount) == 0) {
          ((gp_pthread_recursive_t *)mona)->self_id = 0;	/* Not valid unless mutex is locked */
          scode = pthread_mutex_unlock(mon);

      }
    }
    else {
        scode = -1 /* should be EPERM */;
    }
#endif
    return SEM_ERROR_CODE(scode);
}

static int /* <=== gsicc_get_cspace_hash */ 
gsicc_get_cspace_hash(gsicc_manager_t *icc_manager, gx_device *dev,
                      cmm_profile_t *cmm_icc_profile_data, int64_t *hash)
{
    cmm_dev_profile_t *dev_profile;
    cmm_profile_t *icc_profile;
    gsicc_rendering_param_t render_cond;
    int code;

    if (cmm_icc_profile_data == NULL)
    {
        if (dev == NULL)
            return -1;
        code = dev_proc(dev, get_profile)(dev, &dev_profile);
        if (code < 0)
            return code;
        gsicc_extract_profile(dev->graphics_type_tag, dev_profile,
            &(icc_profile), &render_cond);
        *hash = icc_profile->hashcode;
        return 0;
    }
    if (cmm_icc_profile_data->hash_is_valid ) {
        *hash = cmm_icc_profile_data->hashcode;
    } else {
        /* We need to compute for this color space */
        gsicc_get_icc_buff_hash(cmm_icc_profile_data->buffer, hash,
                                cmm_icc_profile_data->buffer_size);
        cmm_icc_profile_data->hashcode = *hash;
        cmm_icc_profile_data->hash_is_valid = true;
    }
    return 0;
}

void /* <=== gs_transform_color_buffer_generic */ 
gs_transform_color_buffer_generic(byte *inputbuffer,
            int row_stride, int plane_stride,
            int input_num_color, gs_int_rect rect, byte *outputbuffer,
            int output_num_color, int num_noncolor_planes)

{
    int num_rows, num_cols, x, y, z;
    void (* color_remap)(byte input[],byte output[]) = NULL;
    byte input_vector[4],output_vector[4];
    int plane_offset[PDF14_MAX_PLANES],alpha_offset_in,max_num_channels;

    num_rows = rect.q.y - rect.p.y;
    num_cols = rect.q.x - rect.p.x;

    /* Check for spot + cmyk case */

    if (output_num_color > 4)
    {

        /* To CMYK always */
        switch (input_num_color) {

            case 1:
                color_remap = gray_to_cmyk;
                break;

            case 3:
                color_remap = rgb_to_cmyk;
                break;

            case 4:
                color_remap = NULL;        /* Copy data */
                break;

            default:

                /* Should never be here.  Groups must
                   be gray, rgb or CMYK.   Exception
                   may be ICC with XPS */

                break;

        }

    } else {

        /* Pick the mapping to use */

        switch (input_num_color) {

            case 1:
                if (output_num_color == 3)
                    color_remap = gray_to_rgb;
                else
                    color_remap = gray_to_cmyk;
                break;

            case 3:
                if (output_num_color == 1)
                    color_remap = rgb_to_gray;
                else
                    color_remap = rgb_to_cmyk;
                break;

            case 4:
                if (output_num_color == 1)
                    color_remap = cmyk_to_gray;
                else
                    color_remap = cmyk_to_rgb;
                break;

            default:

                /* Should never be here.  Groups must
                   be gray, rgb or CMYK.   Until we
                   have ICC working here with XPS */

                break;

        }

    }

    /* data is planar */

    max_num_channels = max(input_num_color, output_num_color) +
        num_noncolor_planes;

    for (z = 0; z < max_num_channels; z++)
       plane_offset[z] = z * plane_stride;

    if (color_remap == NULL) {

        /* Blending group was CMYK, output is CMYK + spot */

        memcpy(outputbuffer, inputbuffer, 4*plane_stride);

        /* Add any data that are beyond the standard color data (e.g. alpha) */

        if (num_noncolor_planes > 0)
            memcpy(&(outputbuffer[plane_offset[output_num_color]]),
                &(inputbuffer[plane_offset[input_num_color]]),
                num_noncolor_planes*plane_stride);

    } else {

        /* Have to remap */

        alpha_offset_in = input_num_color*plane_stride;

        for (y = 0; y < num_rows; y++) {

           for (x = 0; x < num_cols; x++) {

                /* If the source alpha is transparent, then move on */

                if (inputbuffer[x + alpha_offset_in] != 0x00) {

                    /* grab the input */

                    for (z = 0; z<input_num_color; z++)
                        input_vector[z] = inputbuffer[x+plane_offset[z]];

                    /* convert */

                   color_remap(input_vector,output_vector);

                   /* store the output */

                   for (z = 0; z < output_num_color; z++)
                        outputbuffer[x+plane_offset[z]] = output_vector[z];

                   /* Add any that are beyond the standard color data */

                    for(z = 0; z < num_noncolor_planes; z++)
                        outputbuffer[x + plane_offset[output_num_color+z]] =
                            inputbuffer[x + plane_offset[input_num_color+z]];

                }

            }

            /* update our positions */

            for (z = 0; z < max_num_channels; z++)
                plane_offset[z] += row_stride;

            alpha_offset_in += row_stride;

        }

    }

}

static	void /* <=== pdf14_buf_free */ 
pdf14_buf_free(pdf14_buf *buf, gs_memory_t *memory)
{
    pdf14_parent_color_t *old_parent_color_info = buf->parent_color_info_procs;

    if (buf->mask_stack && buf->mask_stack->rc_mask)
        rc_decrement(buf->mask_stack->rc_mask, "pdf14_buf_free");

    gs_free_object(memory, buf->mask_stack, "pdf14_buf_free");
    gs_free_object(memory, buf->transfer_fn, "pdf14_buf_free");
    gs_free_object(memory, buf->matte, "pdf14_buf_free");
    gs_free_object(memory, buf->data, "pdf14_buf_free");

    while (old_parent_color_info) {
       if (old_parent_color_info->icc_profile != NULL) {
           rc_decrement(old_parent_color_info->icc_profile, "pdf14_buf_free");
       }
       buf->parent_color_info_procs = old_parent_color_info->previous;
       gs_free_object(memory, old_parent_color_info, "pdf14_buf_free");
       old_parent_color_info = buf->parent_color_info_procs;
    }

    gs_free_object(memory, buf->backdrop, "pdf14_buf_free");
    gs_free_object(memory, buf, "pdf14_buf_free");
}

cmm_profile_t * /* <=== gsicc_profile_new */ 
gsicc_profile_new(stream *s, gs_memory_t *memory, const char* pname,
                  int namelen)
{
    cmm_profile_t *result;
    int code;
    char *nameptr = NULL;
    gs_memory_t *mem_nongc = memory->non_gc_memory;

    result = (cmm_profile_t*) gs_alloc_bytes(mem_nongc, sizeof(cmm_profile_t),
                                    "gsicc_profile_new");
    if (result == NULL)
        return result;
    memset(result, 0, GSICC_SERIALIZED_SIZE);
    if (namelen > 0) {
        nameptr = (char*) gs_alloc_bytes(mem_nongc, namelen+1,
                             "gsicc_profile_new");
        if (nameptr == NULL) {
            gs_free_object(mem_nongc, result, "gsicc_profile_new");
            return NULL;
        }
        memcpy(nameptr, pname, namelen);
        nameptr[namelen] = '\0';
        result->name = nameptr;
    } else {
        result->name = NULL;
    }
    result->name_length = namelen;

    /* We may not have a stream if we are creating this
       object from our own constructed buffer.  For
       example if we are converting CalRGB to an ICC type */
    if ( s != NULL) {
        code = gsicc_load_profile_buffer(result, s, mem_nongc);
        if (code < 0) {
            gs_free_object(mem_nongc, result, "gsicc_profile_new");
            gs_free_object(mem_nongc, nameptr, "gsicc_profile_new");
            return NULL;
        }
    } else {
        result->buffer = NULL;
        result->buffer_size = 0;
    }
    rc_init_free(result, mem_nongc, 1, rc_free_icc_profile);
    result->profile_handle = NULL;
    result->spotnames = NULL;
    result->rend_is_valid = false;
    result->isdevlink = false;  /* only used for srcgtag profiles */
    result->dev = NULL;
    result->memory = mem_nongc;
    result->lock = gx_monitor_label(gx_monitor_alloc(mem_nongc),
                                    "gsicc_manage");
    result->vers = ICCVERS_UNKNOWN;
    result->v2_data = NULL;
    result->v2_size = 0;
    result->release = gscms_release_profile; /* Default case */

    if (result->lock == NULL) {
        gs_free_object(mem_nongc, result, "gsicc_profile_new");
        gs_free_object(mem_nongc, nameptr, "gsicc_profile_new");
        return NULL;
    }
    if_debug1m(gs_debug_flag_icc, mem_nongc,
               "[icc] allocating ICC profile = 0x%p\n", result);
    return result;
}

